if(CONFIG_LVX_USE_CONTEST2026_233_HELLO_APP)
  nuttx_add_application(
    NAME ${CONFIG_HELLO_APP_PROGNAME}
    PRIORITY ${CONFIG_HELLO_APP_PRIORITY}
    STACKSIZE ${CONFIG_HELLO_APP_STACKSIZE}
    MODULE ${CONFIG_LVX_USE_CONTEST2026_233_HELLO_APP}
    INCLUDE_DIRECTORIES ${CMAKE_CURRENT_SOURCE_DIR}
    SRCS
      ai_companion_main.c
      ai_state_machine.c
      ai_audio.c
      ai_llm.c
      ai_sound_detect.c
      ai_care.c
      ai_network.c)

  # 添加板级配置头文件路径
  if(CONFIG_ARCH_BOARD_CUSTOM)
    target_include_directories(apps PRIVATE
      ${CONFIG_ARCH_BOARD_CUSTOM_DIR}/include)
  endif()
endif()

